SELECT * FROM SALES LIMIT 10;


-- Total revenue generated by female and male customer
SELECT gender,SUM(purchase_amount) as Revenue FROM SALES GROUP BY gender;

-- Which customer used discount but still spend more than average purchase amount?
SELECT customer_id,purchase_amount
FROM SALES
WHERE  discount_applied="Yes" AND purchase_amount >=(SELECT AVG(purchase_amount) FROM SALES);

-- Which are the top 5 products with highest review rating?
SELECT item_purchased, ROUND(AVG(review_rating),2) as average
FROM SALES GROUP BY item_purchased
ORDER BY average DESC limit 5


-- Compare average purchase amount between Express and Standard shipping
SELECT shipping_type,AVG(purchase_amount) as AVERAGE
FROM SALES
WHERE shipping_type in ("Express","Standard")
GROUP BY shipping_type

-- Do subscribed customer spends more?Compare average spend and total revenue between subscriber and non subscribers
SELECT subscription_status, AVG(purchase_amount) AS Average_spend, SUM(purchase_amount) AS Total_revenue 
FROM SALES 
GROUP BY subscription_status

-- Top 5 product with highest purchase percent and discount applied
SELECT item_purchased, ROUND(SUM(CASE 
    WHEN discount_applied="Yes" THEN 1 
    ELSE  0
END)/COUNT(*)*100 ,2)AS Purchase_Percent
FROM SALES 
GROUP BY  item_purchased
ORDER BY Purchase_Percent DESC
LIMIT 5


-- Segment customer based on previous purchase and show count of each segment
SELECT  (CASE 
    WHEN previous_purchases=1 THEN  "new"
    WHEN previous_purchases BETWEEN 1 AND 10 THEN  "returning"
    ELSE  "loyal"
END) AS customer_type, count(customer_id)
FROM SALES 
GROUP BY customer_type

-- Top 3 product within each category
WITH R AS (SELECT category, item_purchased,COUNT(customer_id)AS TOTALL,ROW_NUMBER()OVER(PARTITION BY category ORDER BY COUNT(customer_id) DESC) AS TOP_PRODUCT
FROM SALES
GROUP BY category ,item_purchased)
SELECT category, item_purchased,TOTALL,TOP_PRODUCT FROM R 
WHERE TOP_PRODUCT <=3

-- Are customer who are repeat buyers are likely to subscribe?
SELECT subscription_status,COUNT(customer_id) as repeatbuyer
FROM sales
WHERE previous_purchases>5
GROUP BY subscription_status

-- Revenue contribution of each age group 
SELECT age_group, SUM(purchase_amount)as total_contribution
FROM sales
GROUP BY age_group



